export default function HomePage() {
  useEffect(() => {
    // 1. Slideshow controller
    let currentSlide = 0;
    const slides = document.querySelectorAll('.slideshow-slide');
    const dots = document.querySelectorAll('[data-slide-button]');
    let slideshowInterval = null;

    function showSlide(idx) {
      currentSlide = idx;
      slides.forEach((s, i) => {
        if (i === idx) {
          s.style.display = 'block';
          s.classList.add('active-slide');
          s.classList.remove('inactive-slide');
        } else {
          s.style.display = 'none';
          s.classList.add('inactive-slide');
          s.classList.remove('active-slide');
        }
      });
      dots.forEach((d, i) => {
        d.setAttribute('data-selected', i === idx ? 'true' : 'false');
      });
    }

    if (slides.length > 0) {
      showSlide(0);
      slideshowInterval = setInterval(() => {
        const next = (currentSlide + 1) % slides.length;
        showSlide(next);
      }, 9000);

      dots.forEach((dot, idx) => {
        dot.addEventListener('click', (e) => {
          e.preventDefault();
          showSlide(idx);
          if (slideshowInterval) clearInterval(slideshowInterval);
          slideshowInterval = setInterval(() => {
            const next = (currentSlide + 1) % slides.length;
            showSlide(next);
          }, 9000);
        });
      });
    }

    // 2. Mobile navigation drawer toggle & close
    const menuBtn = document.querySelector('[data-menu-toggle]');
    const headerNav = document.querySelector('.site-header');
    const closeBtn = document.querySelector('[data-mobile-nav-close]');
    const overlay = document.querySelector('[data-mobile-nav-overlay]');

    const toggleNav = (open) => {
      if (headerNav) {
        if (open === undefined) {
          headerNav.classList.toggle('site-header-nav--open');
        } else if (open) {
          headerNav.classList.add('site-header-nav--open');
        } else {
          headerNav.classList.remove('site-header-nav--open');
        }
      }
    };

    if (menuBtn) {
      menuBtn.addEventListener('click', (e) => {
        e.preventDefault();
        toggleNav();
      });
    }
    if (closeBtn) {
      closeBtn.addEventListener('click', (e) => {
        e.preventDefault();
        toggleNav(false);
      });
    }
    if (overlay) {
      overlay.addEventListener('click', () => {
        toggleNav(false);
      });
    }

    // 3. Back to top button visibility & scroll action
    const bttContainer = document.querySelector('[data-back-to-top]');
    const bttBtn = document.querySelector('.back-to-top__button');

    const handleScroll = () => {
      if (bttContainer) {
        if (window.scrollY > 300) {
          bttContainer.setAttribute('data-animation-state', 'visible');
        } else {
          bttContainer.setAttribute('data-animation-state', 'hidden');
        }
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();

    if (bttBtn) {
      bttBtn.addEventListener('click', (e) => {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });
    }

    // 4. Live search filter label update
    const filterSelect = document.querySelector('[data-live-search-filter]');
    const filterLabel = document.querySelector('[data-live-search-filter-label]');
    if (filterSelect && filterLabel) {
      filterSelect.addEventListener('change', () => {
        const selected = filterSelect.options[filterSelect.selectedIndex];
        filterLabel.textContent = selected ? selected.text : 'All categories';
      });
    }

    
    // 5. FAQ Accordion interactive toggle (Fail-safe: toggles detail.open property and attribute)
    const faqDetails = document.querySelectorAll('.faq__details');
    faqDetails.forEach((detail) => {
      const summary = detail.querySelector('.faq__summary');
      if (summary) {
        summary.onclick = (e) => {
          e.preventDefault();
          e.stopPropagation();
          const nextState = !detail.open;
          detail.open = nextState;
          if (nextState) {
            detail.setAttribute('open', '');
          } else {
            detail.removeAttribute('open');
          }
        };
      }
    });

    return () => {
      if (slideshowInterval) clearInterval(slideshowInterval);
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  return (
    <div dangerouslySetInnerHTML={{ __html: rawHtml }} />
  );
}
